from harness import *
V=180000
# --- Wyciągnij
run('extrude block', BLOCK, V, bbox=([0,0,0],[100,60,30]))
run('extrude negative', [sk(), rect(0,0,100,60), fin(), ext(-30)], V, bbox=([0,0,-30],[100,60,0]))
run('extrude expression', [C('parameters.change', name='h', expression='30 mm'), sk(), rect(0,0,100,60), fin(), ext('h')], V)
run('extrude expr math', [sk(), rect(0,0,100,60), fin(), ext('10 mm + 20 mm')], V)
run('extrude symmetric', [sk(), rect(0,0,100,60), fin(), ext(30, direction='symmetric')], None,
    check=lambda d: None if abs(d['bodies'][0]['bbox']['min'][2] + d['bodies'][0]['bbox']['max'][2]) < 1e-6 else 'not symmetric')
run('extrude two sides', [sk(), rect(0,0,100,60), fin(), ext(10, distance2=20)], V, bbox=([0,0,-20],[100,60,10]))
run('extrude taper out', [sk(), rect(0,0,100,60), fin(), ext(30, taper='5 deg')], None, check=lambda d: None if d['bodies'][0]['volume_mm3']>V else 'taper out not larger')
run('extrude taper in', [sk(), rect(0,0,100,60), fin(), ext(30, taper='-5 deg')], None, check=lambda d: None if d['bodies'][0]['volume_mm3']<V else 'taper in not smaller')
run('extrude circle', [sk(), circ(0,0,10), fin(), ext(20)], PI*100*20)
run('extrude XZ plane', [sk('XZ'), rect(0,0,100,60), fin(), ext(30)], V)
run('extrude YZ plane', [sk('YZ'), rect(0,0,100,60), fin(), ext(30)], V)
run('extrude rect with hole', [sk(), rect(0,0,100,60), circ(50,30,10), fin(), ext(30)], V-PI*100*30)
run('extrude both profiles', [sk(), rect(0,0,100,60), circ(50,30,10), fin(), ext(30, profiles='all')], V)
run('extrude zero distance', [sk(), rect(0,0,100,60), fin(), ext(0)], err=True)
run('extrude offset plane', [C('construct.plane.offset', base='XY', offset=30, name='P1'), sk('P1'), rect(0,0,100,60), fin(), ext(10)], 60000, bbox=([0,0,30],[100,60,40]))
run('extrude on face join', BLOCK+[sk({'face':[50,30,30]}), rect(20,20,40,40), fin(), ext(10, operation='join')], V+4000, bbox=([0,0,0],[100,60,40]))
# --- Wytnij / połącz / przecięcie
run('cut from bottom', BLOCK+[sk(), rect(10,10,30,30), fin(), ext(10, operation='cut')], V-4000)
run('cut through all', BLOCK+[sk(), circ(50,30,10), fin(), C('solid.extrude', through_all=True, operation='cut')], V-PI*100*30)
run('cut on face negative', BLOCK+[sk({'face':[50,30,30]}), rect(20,20,40,40), fin(), ext(-10, operation='cut')], V-4000)
run('cut on face auto op', BLOCK+[sk({'face':[50,30,30]}), rect(20,20,40,40), fin(), ext(-10, operation='auto')], V-4000)
#run('cut missing body', BLOCK+[sk(), rect(200,200,220,220), fin(), ext(10, operation='cut')], err=True)
run('join overlap', BLOCK+[sk(), rect(90,0,150,60), fin(), ext(30, operation='join')], 150*60*30)
run('new body', BLOCK+[sk(), rect(200,0,220,20), fin(), ext(10, operation='new')], V+4000, bodies=2)
run('intersect', BLOCK+[sk(), rect(50,0,150,60), fin(), ext(30, operation='intersect')], 50*60*30)
run('cut splits body', BLOCK+[sk(), rect(45,-5,55,65), fin(), ext(30, operation='cut')], V-10*60*30, bodies=2)
# --- Obrót
run('revolve 360', [sk('XZ'), rect(10,0,20,30), fin(), C('solid.revolve', axis='Z')], PI*(400-100)*30)
run('revolve 180', [sk('XZ'), rect(10,0,20,30), fin(), C('solid.revolve', axis='Z', angle='180 deg')], PI*(400-100)*30/2)
run('revolve symmetric 90', [sk('XZ'), rect(10,0,20,30), fin(), C('solid.revolve', axis='Z', angle='90 deg', direction='symmetric')], PI*(400-100)*30/4)
run('revolve touching axis', [sk('XZ'), rect(0,0,20,30), fin(), C('solid.revolve', axis='Z')], PI*400*30)
run('revolve crossing axis', [sk('XZ'), rect(-10,0,20,30), fin(), C('solid.revolve', axis='Z')], err=True)
run('revolve cut', BLOCK+[sk('XZ'), rect(55,-30,65,-25), fin(), C('solid.revolve', axis={'origin':[50,0,30],'dir':[0,0,1]}, operation='cut')], V-PI*(225-25)*5/2)
# --- Zaokrąglij
f1 = V-(25-PI*25/4)*100
run('fillet one edge', BLOCK+[C('solid.fillet', edges=[[50,0,30]], radius=5)], f1)
run('fillet 4 vertical', BLOCK+[C('solid.fillet', edges=[[0,0,15],[100,0,15],[100,60,15],[0,60,15]], radius=5)], V-(25-PI*25/4)*30*4)
run('fillet expression', BLOCK+[C('parameters.change', name='r', expression='5 mm'), C('solid.fillet', edges=[[50,0,30]], radius='r')], f1)
run('fillet too big', BLOCK+[C('solid.fillet', edges=[[50,0,30]], radius=40)], err=True)
run('fillet chain top', BLOCK+[C('solid.fillet', edges=[[50,0,30],[100,30,30],[50,60,30],[0,30,30]], radius=3)], None)
run('fillet all 12', BLOCK+[C('solid.fillet', edges=[[50,0,30],[100,30,30],[50,60,30],[0,30,30],[50,0,0],[100,30,0],[50,60,0],[0,30,0],[0,0,15],[100,0,15],[100,60,15],[0,60,15]], radius=3)], None)
run('fillet variable', BLOCK+[C('solid.fillet', edges=[[50,0,30]], radius=2, radius2=6, type='variable', start=[0,0,30])], None)
run('fillet after cut', BLOCK+[sk(), circ(50,30,10), fin(), C('solid.extrude', through_all=True, operation='cut'), C('solid.fillet', edges=[[60,30,30]], radius=2)], None)
# --- Fazuj
run('chamfer one edge', BLOCK+[C('solid.chamfer', edges=[[50,0,30]], distance=5)], V-12.5*100)
run('chamfer two dist', BLOCK+[C('solid.chamfer', edges=[[50,0,30]], distance=5, distance2=10)], V-25*100)
run('chamfer angle', BLOCK+[C('solid.chamfer', edges=[[50,0,30]], distance=5, angle='45 deg')], V-12.5*100)
run('chamfer 4 top', BLOCK+[C('solid.chamfer', edges=[[50,0,30],[100,30,30],[50,60,30],[0,30,30]], distance=2)], None)
run('chamfer too big', BLOCK+[C('solid.chamfer', edges=[[50,0,30]], distance=35)], err=True)
# --- Skorupa
run('shell open top', BLOCK+[C('solid.shell', faces=[[50,30,30]], thickness=2)], V-96*56*28)
run('shell outside', BLOCK+[C('solid.shell', faces=[[50,30,30]], thickness=2, direction='outside')], 104*64*32-V)
#run('shell closed', BLOCK+[C('solid.shell', faces=[], thickness=2)], V-96*56*26)
run('shell two faces', BLOCK+[C('solid.shell', faces=[[50,30,30],[50,0,15]], thickness=2)], None)
run('shell too thick', BLOCK+[C('solid.shell', faces=[[50,30,30]], thickness=40)], err=True)
# --- Otwór
run('hole through', BLOCK+[C('solid.hole', position=[50,30,30], diameter=10)], V-PI*25*30)
run('hole depth', BLOCK+[C('solid.hole', position=[50,30,30], diameter=10, depth=10)], None, check=lambda d: None if V-PI*25*12 < d['bodies'][0]['volume_mm3'] < V-PI*25*9.9 else f"depth hole volume {d['bodies'][0]['volume_mm3']:.0f}")
run('hole clearance M6', BLOCK+[C('solid.hole', position=[50,30,30], clearance='M6')], V-PI*(6.6/2)**2*30, tol=5e-3)
run('hole thread M8', BLOCK+[C('solid.hole', position=[50,30,30], thread='M8')], None)
run('hole side face', BLOCK+[C('solid.hole', position=[50,0,15], diameter=8)], V-PI*16*60)
run('hole sketch points', BLOCK+[sk({'face':[50,30,30]}), C('sketch.point', point=[20,20]), C('sketch.point', point=[80,40]), fin(), C('solid.hole', sketch='Sketch2', diameter=6)], V-2*PI*9*30)
run('hole off body', BLOCK+[C('solid.hole', position=[200,30,30], diameter=10)], err=True)
# --- Wciśnij/wyciągnij ścianę
run('press pull out', BLOCK+[C('solid.press_pull', face=[50,30,30], distance=10)], 240000)
run('press pull in', BLOCK+[C('solid.press_pull', face=[50,30,30], distance=-10)], 120000)
run('press pull side', BLOCK+[C('solid.press_pull', face=[100,30,15], distance=20)], 120*60*30)
# --- Przesuń
run('move translate', BLOCK+[C('solid.move', bodies=['Body1'], translate=[10,20,5])], V, bbox=([10,20,5],[110,80,35]))
run('move rotate', BLOCK+[C('solid.move', bodies=['Body1'], axis=[0,0,1], angle='90 deg')], V, bbox=([-60,0,0],[0,100,30]))
run('move copy', BLOCK+[C('solid.move', bodies=['Body1'], translate=[200,0,0], copy=True)], 2*V, bodies=2)
# --- Lustro
run('mirror body combine', BLOCK+[C('solid.mirror', bodies=['Body1'], plane='YZ', combine=True)], 2*V, bbox=([-100,0,0],[100,60,30]))
run('mirror body', BLOCK+[C('solid.mirror', bodies=['Body1'], plane='YZ')], 2*V, bodies=2)
run('mirror feature', BLOCK+[sk(), circ(20,30,5), fin(), C('solid.extrude', through_all=True, operation='cut'), C('solid.mirror', features=['Extrude2'], plane={'origin':[50,0,0],'normal':[1,0,0]})], V-2*PI*25*30)
# --- Szyk
run('pattern body', BLOCK+[C('solid.pattern.rectangular', bodies=['Body1'], dir1=[1,0,0], count1=3, spacing1=150)], 3*V, bodies=3)
run('pattern feature', BLOCK+[sk(), circ(20,30,5), fin(), C('solid.extrude', through_all=True, operation='cut'), C('solid.pattern.rectangular', features=['Extrude2'], dir1=[1,0,0], count1=4, spacing1=20)], V-4*PI*25*30)
run('pattern 2d', BLOCK+[sk(), circ(20,15,4), fin(), C('solid.extrude', through_all=True, operation='cut'), C('solid.pattern.rectangular', features=['Extrude2'], dir1=[1,0,0], count1=3, spacing1=30, dir2=[0,1,0], count2=2, spacing2=30)], V-6*PI*16*30)
run('pattern off body', BLOCK+[sk(), circ(20,30,5), fin(), C('solid.extrude', through_all=True, operation='cut'), C('solid.pattern.rectangular', features=['Extrude2'], dir1=[1,0,0], count1=10, spacing1=20)], None)
# --- Parametry
run('param drives model', [C('parameters.change', name='w', expression='100 mm'), sk(), C('sketch.rectangle.two_point', p0=[0,0], p1=['w',60]), fin(), ext(30), C('parameters.change', name='w', expression='50 mm')], 50*60*30)
run('extrude to object', BLOCK+[C('construct.plane.offset', base='XY', offset=50, name='P1'), sk('P1'), rect(10,10,30,30), fin(), C('solid.extrude', to=[50,30,30], operation='join')], V+400*20)
run('extrude start offset', [sk(), rect(0,0,100,60), fin(), ext(30, start_offset=10)], V, bbox=([0,0,10],[100,60,40]))
run('extrude through all both', BLOCK+[C('construct.plane.offset', base='XY', offset=15, name='Mid'), sk('Mid'), circ(50,30,5), fin(), C('solid.extrude', through_all=True, direction='symmetric', operation='cut')], V-PI*25*30)
run('extrude open profile', [sk(), C('sketch.line', points=[[0,0],[50,0],[50,50]]), fin(), ext(10)], err=True)
run('extrude thin open', [sk(), C('sketch.line', points=[[0,0],[50,0],[50,50]]), fin(), ext(10, thin=True, thickness=2)], None)
summary()
